$ErrorActionPreference='Stop'
Import-Module (Join-Path $PSScriptRoot 'Repato.MayaQaWorkflow.psm1') -Force -WarningAction SilentlyContinue
Import-Module (Join-Path $PSScriptRoot 'Repato.AgentOrchestration.psm1') -Force -WarningAction SilentlyContinue
Import-Module (Join-Path $PSScriptRoot 'Repato.Deployment.v4.psm1') -Force -WarningAction SilentlyContinue

function New-Case {
    $root=Join-Path ([IO.Path]::GetTempPath()) ('frozen-evidence-'+[guid]::NewGuid().ToString('N'));$candidate=Join-Path $root 'candidate';$store=Join-Path $root 'store';New-Item $candidate -ItemType Directory -Force|Out-Null
    $dll=Join-Path $candidate 'Repato.Revit.dll';$manifest=Join-Path $candidate 'Repato.addin';[IO.File]::WriteAllText($dll,'synthetic frozen dll');Set-Content $manifest '<RevitAddIns />';$hash=(Get-FileHash $dll -Algorithm SHA256).Hash;$commit='1234567890abcdef1234567890abcdef12345678';@{CandidateType='SyntheticReleaseCandidate';SourceCommit=$commit;FrozenArtifactSha256=$hash;SupportedQaWorkflows=@('create-plan-views-v1')}|ConvertTo-Json|Set-Content (Join-Path $candidate 'release-manifest.json')
    $runnerManifest=Join-Path $PSScriptRoot '..\QA\Repato.CreatePlanViews.TestRunner.addin';$runnerManifest=[IO.Path]::GetFullPath($runnerManifest);$runnerHash=(Get-FileHash $runnerManifest -Algorithm SHA256).Hash
    $b=New-MayaQaBootstrap -StoreRoot $store -QaWorkflowId create-plan-views-v1 -RunId ('run-'+[guid]::NewGuid().ToString('N'));New-MayaQaBuildRequest -StoreRoot $store -TaskId $b.TaskId -WorkflowId $b.WorkflowId -QaWorkflowId 'create-plan-views-v1' -UserRequest 'Create Plan Views' -SourceBranch synthetic -ProjectPath synthetic.csproj|Out-Null;$w=Get-DeployWorkflow $store $b.TaskId $b.WorkflowId;$t=Find-RepatoTask (Read-RepatoTaskStore $store) $b.TaskId;Invoke-RepatoWorkflowMutation $store $b.TaskId $b.WorkflowId $w.workflowRevision $t.revision {param($x)$x|Add-Member NoteProperty qaBuildStatus 'succeeded' -Force;$x|Add-Member NoteProperty qaBuildEvidence ([pscustomobject]@{BuildRequestId=$x.qaBuildRequest.BuildRequestId;BuildStatus='succeeded';SourceCommit=$commit;ExitCode=0;Configuration='Release';ArtifactPath=$dll;ArtifactSha256=$hash;ManifestPath=$manifest;ManifestSha256=(Get-FileHash $manifest).Hash;RunnerManifestPath=$runnerManifest;RunnerManifestSha256=$runnerHash}) -Force;$x}|Out-Null
    [pscustomobject]@{Root=$root;Candidate=$candidate;Store=$store;TaskId=$b.TaskId;WorkflowId=$b.WorkflowId;Hash=$hash;Commit=$commit;ManifestPath=$runnerManifest;ManifestHash=$runnerHash}
}
function New-Response($c){[pscustomobject]@{schemaVersion=1;operation='validate-qa-deployment';requestId='synthetic-request';succeeded=$true;candidateCommit=$c.Commit;candidateSha256=$c.Hash;qaWorkflowId='create-plan-views-v1';testId='create-plan-views-v1';validationIdentity='Ramsai\RepatoQA';qaAddinRoot='C:\Users\RepatoQA\AppData\Roaming\Autodesk\Revit\Addins\2025\RepatoQA';runnerManifestPath=$c.ManifestPath;runnerManifestSha256=$c.ManifestHash;validatedRunnerManifestPath=$c.ManifestPath;manifestIntegrityEvidenceAvailable=$false;isolationPassed=$true}
}
function Invoke-Case([string]$Name,[scriptblock]$Mutate,[bool]$ShouldPass){$c=New-Case;try{$r=New-Response $c;&$Mutate $r;$result=$null;$rejected=$false;try{$result=Invoke-MayaQaFrozenCandidateEvidence -StoreRoot $c.Store -TaskId $c.TaskId -WorkflowId $c.WorkflowId -QaWorkflowId 'create-plan-views-v1' -CandidateDirectory $c.Candidate -ExpectedSha256 $c.Hash -ExpectedSourceCommit $c.Commit -DeploymentEvidence $r}catch{$rejected=$true;$error=$_.Exception.Message};if($ShouldPass){if($rejected){throw $error};$w=Get-DeployWorkflow $c.Store $c.TaskId $c.WorkflowId;$e=$w.qaBuildEvidence;if($result.BuildStatus -ne 'succeeded' -or !$result.ArtifactPath -or !$result.ManifestPath -or $e.QaWorkflowId -ne 'create-plan-views-v1' -or $e.ArtifactSha256 -ne $c.Hash -or $e.RunnerManifestPath -ne $c.ManifestPath -or $e.RunnerManifestSha256 -ne $c.ManifestHash -or !$e.Isolation.Allowed){throw 'Normalized frozen-candidate evidence was incomplete.'}}elseif(!$rejected){throw "$Name was accepted."};[pscustomobject]@{Name=$Name;Passed=$true;Rejected=$rejected;Error=$error}}finally{Remove-Item $c.Root -Recurse -Force -ErrorAction SilentlyContinue}}
$valid=Invoke-Case 'real-response-shape' {param($r)} $true
$falseCase=Invoke-Case 'isolationPassed-false' {param($r)$r.isolationPassed=$false} $false
$missingCase=Invoke-Case 'missing-isolation-evidence' {param($r)$r.PSObject.Properties.Remove('isolationPassed')} $false
$malformedCase=Invoke-Case 'malformed-isolation-evidence' {param($r)$r|Add-Member NoteProperty Isolation ([pscustomobject]@{PolicyPath='x'}) -Force;$r.PSObject.Properties.Remove('isolationPassed')} $false
@{Status='PASS';RealResponseShapeRegression=$valid.Passed;IsolationFalseRejected=$falseCase.Passed;MissingIsolationRejected=$missingCase.Passed;MalformedIsolationRejected=$malformedCase.Passed;PropertyNotFoundStrictErrors=0;RevitLaunched=$false;LivePipeRequestSent=$false}|ConvertTo-Json -Compress
